export interface Post {
  id: number
  title: string
  body: string
  userId?: number
}

export interface Comment {
  id: number
  name: string
  email: string
  body: string
  postId?: number
}

export interface LocalPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

import { Post, Comment } from '@/types'

const BASE_URL = 'https://jsonplaceholder.typicode.com'

export async function fetchPosts(limit?: number): Promise<Post[]> {
  const url = limit
    ? `${BASE_URL}/posts?_limit=${limit}`
    : `${BASE_URL}/posts`

  const response = await fetch(url)

  if (!response.ok) {
    throw new Error('Failed to fetch posts')
  }

  return response.json()
}

export async function fetchPostById(id: string): Promise<Post> {
  const response = await fetch(`${BASE_URL}/posts/${id}`)

  if (!response.ok) {
    throw new Error(`Failed to fetch post ${id}`)
  }

  return response.json()
}

export async function fetchCommentsByPostId(id: string): Promise<Comment[]> {
  const response = await fetch(`${BASE_URL}/posts/${id}/comments`)

  if (!response.ok) {
    throw new Error(`Failed to fetch comments for post ${id}`)
  }

  return response.json()
}

