import { NextRequest, NextResponse } from 'next/server'
import type { LocalPost } from '@/types'

const posts: LocalPost[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

export async function GET(): Promise<NextResponse<LocalPost[]>> {
  return NextResponse.json(posts)
}

interface CreatePostBody {
  title?: string
  content?: string
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  const body = (await request.json()) as CreatePostBody
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: LocalPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  posts.push(newPost)

  return NextResponse.json(newPost, { status: 201 })
}

import { NextRequest, NextResponse } from 'next/server'
import type { LocalPost } from '@/types'

interface RouteParams {
  params: Promise<{ id: string }>
}

export async function GET(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<LocalPost>> {
  const { id } = await params

  const post: LocalPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

interface UpdatePostBody {
  title?: string
  content?: string
}

export async function PUT(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<LocalPost>> {
  const { id } = await params
  const body = (await request.json()) as UpdatePostBody
  const { title, content } = body

  const updatedPost: LocalPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<{ message: string }>> {
  const { id } = await params

  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

